#!/usr/bin/env bash
# Write Agent version files from git tags (same source as Makefile BUDDY_VERSION / PKG_VERSION).
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"

describe="$(git -C "$root" describe --tags --always --dirty 2>/dev/null || echo dev)"
marketing="$(printf '%s' "$describe" | sed -E 's/^v//;s/-.*//')"
test -n "$marketing" || marketing=0.0.0

swift="$root/macos/BuddyAgent/Sources/BuddyAgent/AgentVersion.generated.swift"
xcconfig="$root/macos/BuddyAgent/Version.xcconfig"

mkdir -p "$(dirname "$swift")"
cat >"$swift" <<SWIFT
// Code generated by scripts/gen-agent-version.sh; DO NOT EDIT.

enum AgentBuildVersion {
	/// Full \`git describe\` string (buddy CLI \`main.Version\`).
	static let describe = "$describe"
	/// Period-delimited semver for CFBundleShortVersionString / pkgbuild.
	static let marketing = "$marketing"
}
SWIFT

cat >"$xcconfig" <<XCC
// Code generated by scripts/gen-agent-version.sh; DO NOT EDIT.
MARKETING_VERSION = $marketing
CURRENT_PROJECT_VERSION = 1
XCC

echo "gen-agent-version: describe=$describe marketing=$marketing"
